contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // run attempts a withdrawAll call with given recipient and an amount of ether previously sent to C
    function run(address payable recipient, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        // fund C with `amount` ether from this contract
        // send ether to C using its fallback
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        // record balances before withdraw
        uint balBeforeC = address(c).balance;
        uint balBeforeRecipient = recipient.balance;
        address owner = c.owner();

        // try to call withdrawAll as this contract (msg.sender == address(this))
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint balAfterC = address(c).balance;
        uint balAfterRecipient = recipient.balance;

        // Assertion: If call did not revert, it must have been invoked by the owner and all ether moved from C to recipient.
        // If it did not revert then msg.sender must equal owner (i.e. this contract is owner) and C balance becomes zero
        // and recipient gained exactly balBeforeC.
        assert(
            reverted || (
                owner == address(this) &&
                balAfterC == 0 &&
                balAfterRecipient == balBeforeRecipient + balBeforeC
            )
        );
    }

    receive() external payable {}
}

