contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run a single scenario: deployer (this contract) may or may not be owner of c.
    // Params:
    // - callerIsOwner: if true, we will call withdrawAll as the owner by using address(this) as owner; otherwise owner is some other external address.
    // - depositAmount: amount of Ether to send into c before withdrawal.
    // - recipient: where funds will be sent by withdrawAll.
    function run(bool callerIsOwner, uint depositAmount, address payable recipient) public payable {
        require(msg.sender == msg.sender); // no-op to satisfy template (keeps function body non-empty regarding require)
        // If callerIsOwner is true, we need c.owner() == address(this). The deployed c is fresh and its constructor was given some owner;
        // We cannot redeploy c. But we can only observe public owner and act accordingly: if callerIsOwner is true we require that c.owner()==address(this), otherwise require it's != address(this).
        // These are preconditions that the checker will satisfy by choosing parameters accordingly.
        if (callerIsOwner) {
            require(c.owner() == address(this));
        } else {
            require(c.owner() != address(this));
        }

        // To deposit Ether into c, send depositAmount from this contract
        // Ensure this contract has enough balance for the deposit
        require(address(this).balance >= depositAmount);
        if (depositAmount > 0) {
            // call fallback by sending Ether
            (bool ok,) = address(c).call{value: depositAmount}("");
            require(ok);
        }

        // Record balances before calling withdrawAll
        uint balBeforeC = address(c).balance;
        uint balBeforeThis = address(this).balance;
        uint balBeforeRecipient = recipient.balance;

        // Make the deciding call and capture whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint balAfterC = address(c).balance;
        uint balAfterThis = address(this).balance;
        uint balAfterRecipient = recipient.balance;

        // Assert the general rule:
        // - If caller is owner, withdrawAll must not revert, c's balance becomes zero, and recipient gains exactly balBeforeC.
        // - If caller is not owner, withdrawAll must revert and balances unchanged.
        assert(
            (callerIsOwner && !reverted && balAfterC == 0 && balAfterRecipient == balBeforeRecipient + balBeforeC)
            ||
            (!callerIsOwner && reverted && balAfterC == balBeforeC && balAfterRecipient == balBeforeRecipient)
        );
    }

    receive() external payable { }
}

