contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // run takes caller (attempting withdrawer) and recipient and an initial funding amount to send to c
    function run(address caller, address payable recipient, uint256 fund) public payable {
        require(address(this).balance >= fund);
        // fund the contract c with `fund` wei from this contract
        // send Ether to c using its fallback by sending to address(c)
        (bool sf,) = address(c).call{value: fund}("");
        // call may or may not accept funds, but c has payable fallback so it should succeed
        // read before values
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        address owner = c.owner();

        // Now attempt withdrawAll from the perspective of `caller` by using a low-level call
        // We encode the selector and argument for withdrawAll(address)
        bytes memory payload = abi.encodeWithSignature("withdrawAll(address)", recipient);
        bool reverted;
        // perform call as `caller` by using address(this).call and specifying from via creating a contract is impossible here,
        // but we can simulate calls from different msg.sender by calling c directly: since the checker deploys c and then
        // runs this contract as msg.sender, only this contract is the caller to c. To model `caller`, we check two cases:
        // - if caller == owner then this contract should behave as owner only if owner equals address(this).
        // So instead we invoke withdraw and record whether it reverted. The property will relate revert status to whether caller == owner
        // To actually vary msg.sender, we use the following: if caller == address(this) we call directly; otherwise we perform a low-level call
        // from this contract to c but using the provided payload; msg.sender for c will always be this contract. Therefore, the only meaningful
        // variation is whether owner equals address(this). We therefore require caller to equal address(this) to express the intended relation.
        // Enforce that precondition so the test is meaningful and provable.
        require(caller == address(this));

        // perform the withdraw attempt as this contract
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // If the caller (this contract) is the owner, the call must not revert, c's balance becomes zero, and recipient balance increases by beforeC.
        // If the caller is not the owner, the call must revert and c's balance is unchanged and recipient balance is unchanged.
        if (owner == address(this)) {
            assert(!reverted && afterC == 0 && afterRecipient == beforeRecipient + beforeC);
        } else {
            assert(reverted && afterC == beforeC && afterRecipient == beforeRecipient);
        }
    }
    receive() external payable {}
}

