contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run takes a recipient and an amount to fund the contract before the withdrawal attempt,
    // and a callerIsOwner flag indicating whether this contract should act as owner or not.
    // To simulate calls from either owner or non-owner, we rely on the fact that c was
    // constructed externally; msg.sender for calls from this contract is this contract
    // itself. If we want the InvMutTest to be the owner, the provided C instance must
    // have been constructed with address(this) as owner. The property checks behavior
    // for both cases by observing c.owner().
    function run(address payable recipient, uint256 amount, bool callAsOwner) public payable {
        require(address(this).balance >= amount);

        // Fund the target contract c with the provided amount so there's something to withdraw.
        // We send the Ether from this contract to c.
        (bool sent, ) = address(c).call{value: amount}("\x00");
        // The fallback of C is payable so this should succeed; require to ensure setup proceeds.
        require(sent);

        uint256 beforeBalance = address(c).balance;
        address ownerAddr = c.owner();

        bool reverted;
        // Decide whether to attempt the withdraw as owner (this contract must be owner) or as non-owner.
        // We cannot change msg.sender, so if callAsOwner is true but this contract is not the owner,
        // the call will behave like a non-owner attempt. The property will relate the observed owner
        // and the revert/result.
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;

        // General rule:
        // - If this contract is the owner (ownerAddr == address(this)) then withdrawAll must not revert
        //   and the contract's balance must decrease by exactly beforeBalance (i.e., become zero),
        //   and the recipient must have been able to receive the funds (we observe by address(this).balance
        //   possibly increasing only if recipient == address(this); otherwise we at least observe contract balance).
        // - If this contract is not the owner then withdrawAll must revert and the contract balance must be unchanged.
        if (ownerAddr == address(this)) {
            // when owner, call should succeed (not revert) and drain the contract
            assert(reverted == false && afterBalance == 0);
        } else {
            // when not owner, call must revert and balance unchanged
            assert(reverted == true && afterBalance == beforeBalance);
        }
    }

    // Allow receiving Ether for test setup
    receive() external payable {}
}

